{
  "name": "CC1 手持式符合计数器",
  "name_en": "CC1 Hand-Held Coincidence Counter",
  "manufacturer": "Qubitekk",
  "description": "CC1 是一款手持式符合计数器，用于统计两路探测信号在设定时间窗内的符合事件，并记录各通道计数。它可设置符合时间窗、积分/驻留时间、触发模式、门控和延迟等参数，适用于量子光学、单光子探测和时间相关计数实验中的符合测量。",
  "description_en": "The CC1 is a hand-held coincidence counter used to measure coincidence events between two detection signals within a defined time window and to track channel counts. It supports settings such as coincidence window, dwell/integration time, trigger mode, gating, and delay, making it suitable for coincidence measurements in quantum optics, single-photon detection, and time-correlated counting experiments.",
  "tag_hints": [
    "coincidence counting",
    "single-photon detection",
    "quantum optics",
    "time-correlated measurements",
    "nanosecond timing window",
    "event counting",
    "handheld instrument"
  ],
  "actions": [
    {
      "action_name": "auto-acknowledge",
      "description": "获取/设置命令回显确认状态",
      "description_en": "Get/set the command acknowledge echo state."
    },
    {
      "action_name": "auto-clear_counts",
      "description": "清除当前累计计数",
      "description_en": "Clear the current total counts."
    },
    {
      "action_name": "auto-delay",
      "description": "获取/设置通道 1 的延迟时间",
      "description_en": "Get/set the delay on Channel 1."
    },
    {
      "action_name": "auto-dwell_time",
      "description": "获取/设置驻留时间",
      "description_en": "Get/set the dwell time."
    },
    {
      "action_name": "auto-gate",
      "description": "获取/设置门控使能状态",
      "description_en": "Get/set the gate enable state."
    },
    {
      "action_name": "auto-subtract",
      "description": "获取/设置减法功能使能状态",
      "description_en": "Get/set the subtract enable state."
    },
    {
      "action_name": "auto-trigger_mode",
      "description": "获取/设置触发模式",
      "description_en": "Get/set the trigger mode."
    },
    {
      "action_name": "auto-window",
      "description": "获取/设置符合时间窗长度",
      "description_en": "Get/set the coincidence window length."
    },
    {
      "action_name": "auto-firmware",
      "description": "获取固件版本",
      "description_en": "Get the firmware version."
    },
    {
      "action_name": "auto-channel",
      "description": "获取指定计数通道",
      "description_en": "Get a specified counting channel."
    },
    {
      "action_name": "auto-count",
      "description": "获取通道计数值",
      "description_en": "Get the channel count value."
    }
  ]
}

